import { parse24HourTime } from '../utils/i18n';
/**
 * This class purposefully has functions that match those from Date.
 * The reason is so someone wanting to pass a Date object into the pds-time-widget, or the
 * validation engine time rules they can do so and the code won't break.
 */
export class SimpleTime {
    constructor(hours, minutes, seconds) {
        if (typeof hours === 'number') { // Positive or negative integer
            this.setHours(hours);
            this.setMinutes(minutes || 0);
            this.setSeconds(seconds || 0);
        }
        else if (typeof hours === 'string') {
            const parsedTime = parse24HourTime(hours); // This means 24 hour time is given in the format of HH:mm OR HH:mm:ss
            if (parsedTime != null) {
                this.set(parsedTime);
            }
        }
        else {
            this.setHours(0);
            this.setMinutes(0);
            this.setSeconds(0);
        }
    }
    to24HourTime() {
        let hours = this.getHours();
        let minutes = this.getMinutes();
        let seconds = this.getSeconds();
        if (hours < 10) {
            hours = '0' + hours;
        }
        if (minutes < 10) {
            minutes = '0' + minutes;
        }
        if (seconds < 10) {
            seconds = '0' + seconds;
        }
        return hours + ':' + minutes + ':' + seconds;
    }
    getHours() {
        return this.hours;
    }
    getMinutes() {
        return this.minutes;
    }
    getSeconds() {
        return this.seconds;
    }
    setHours(hours) {
        const hrs = hours % 24;
        if (hrs >= 0) {
            this.hours = hrs;
        }
        else {
            // hours are negative, so lets add 24 to the remainder given from modulus 24 operator
            this.hours = 24 + hrs;
        }
    }
    setMinutes(minutes) {
        const overHours = Math.floor(minutes / 60);
        this.setHours(this.hours + overHours);
        const mins = minutes % 60;
        if (mins >= 0) {
            this.minutes = mins;
        }
        else {
            //60 - min, but min is already negative
            this.minutes = 60 + mins;
        }
    }
    setSeconds(seconds) {
        const overMinutes = Math.floor(seconds / 60);
        this.setMinutes(this.minutes + overMinutes);
        const secs = seconds % 60;
        if (secs >= 0) {
            this.seconds = secs;
        }
        else {
            //60 - min, but min is already negative
            this.seconds = 60 + secs;
        }
    }
    getTime() {
        return (this.hours * 60 * 60 + this.getMinutes() * 60 + this.getSeconds()) * 1000;
    }
    set(time) {
        this.setHours(time.getHours());
        this.setMinutes(time.getMinutes());
        this.setSeconds(time.getSeconds());
    }
}
